#define ROL64(x, n) ((n) ? (((x) << (n)) | ((x) >> (64 - (n)))) : (x))
#ifndef KF_RHO_BAD
#define KF_RHO_BAD 0
#endif
static u64 RC[24];
static u8 RHO[25];
// rc(t): bit 0 of x^t mod (x^8 + x^6 + x^5 + x^4 + 1); RC[ir] has bit 2^j - 1 equal to rc(j + 7 ir) for j = 0..6.
static void init_constants(void) {
    unsigned r = 1; u8 rcbit[7 * 24 + 7];
    for (int t = 0; t < 7 * 24 + 7; t++) { rcbit[t] = (u8)(r & 1); r <<= 1; if (r & 0x100) r ^= 0x171; }
    for (int ir = 0; ir < 24; ir++) { RC[ir] = 0; for (int j = 0; j < 7; j++) if (rcbit[j + 7 * ir]) RC[ir] |= 1ull << ((1 << j) - 1); }
    // rho: lane (0,0) is 0; walking (x,y) -> (y, 2x+3y) from (1,0), step t has offset (t+1)(t+2)/2 mod 64.
    for (int i = 0; i < 25; i++) RHO[i] = 0;
    int x = 1, y = 0;
    for (int t = 0; t < 24; t++) { RHO[x + 5 * y] = (u8)(((t + 1) * (t + 2) / 2) % 64); int nx = y, ny = (2 * x + 3 * y) % 5; x = nx; y = ny; }
    RHO[1] = (u8)(RHO[1] + KF_RHO_BAD);
}
static void theta(u64 a[25]) {
    u64 c[5], d[5];
    for (int x = 0; x < 5; x++) c[x] = a[x] ^ a[x + 5] ^ a[x + 10] ^ a[x + 15] ^ a[x + 20];
    for (int x = 0; x < 5; x++) d[x] = c[(x + 4) % 5] ^ ROL64(c[(x + 1) % 5], 1);
    for (int i = 0; i < 25; i++) a[i] ^= d[i % 5];
}
static void rho(u64 a[25]) { for (int i = 0; i < 25; i++) a[i] = ROL64(a[i], RHO[i]); }
static void pi(u64 a[25]) {
    u64 b[25];
    for (int x = 0; x < 5; x++) for (int y = 0; y < 5; y++) b[y + 5 * ((2 * x + 3 * y) % 5)] = a[x + 5 * y];
    for (int i = 0; i < 25; i++) a[i] = b[i];
}
static void chi(u64 a[25]) {
    u64 b[25];
    for (int i = 0; i < 25; i++) b[i] = a[i];
    for (int y = 0; y < 5; y++) for (int x = 0; x < 5; x++) a[x + 5 * y] = b[x + 5 * y] ^ (~b[(x + 1) % 5 + 5 * y] & b[(x + 2) % 5 + 5 * y]);
}
static void iota(u64 a[25], int ir) { a[0] ^= RC[ir]; }

static int check_example(int n, const u64 *in, const u64 *steps, const u8 *fin) {
    u64 a[25]; int good = 0; static const char *const nm[5] = {"theta", "rho", "pi", "chi", "iota"};
    for (int i = 0; i < 25; i++) a[i] = in[i];
    for (int r = 0; r < 24; r++) {
        int okr = 1;
        for (int s = 0; s < 5; s++) {
            if (s == 0) theta(a); else if (s == 1) rho(a); else if (s == 2) pi(a); else if (s == 3) chi(a); else iota(a, r);
            const u64 *want = steps + (r * 5 + s) * 25;
            int ok = 1; for (int i = 0; i < 25; i++) if (a[i] != want[i]) ok = 0;
            good += ok; if (!ok) { okr = 0; pstr("FAIL example "); pdec(n); pstr(" round "); pdec(r); pstr(" after "); pstr(nm[s]); pstr("\n"); }
        }
        pstr(okr ? "PASS" : "FAIL"); pstr(" example "); pdec(n); pstr(" round "); pdec(r); pstr(": 5 steps\n");
    }
    u8 out[200]; for (int i = 0; i < 200; i++) out[i] = (u8)(a[i / 8] >> (8 * (i % 8)));
    char nmb[32]; const char *p = "example 0 output"; int k = 0; while (*p) nmb[k++] = *p++; nmb[k] = 0; nmb[8] = (char)('0' + n);
    good += pcheck_bytes(nmb, out, fin, 200);
    return good;
}
int paper_main(void) {
    init_constants();
    int good = 0, rcok = 0, rhook = 0;
    for (int i = 0; i < 24; i++) rcok += RC[i] == RC_PUB[i];
    for (int i = 0; i < 25; i++) rhook += RHO[i] == RHO_PUB[i];
    pstr("round constants: "); pdec(rcok); pstr(" of 24 match\n");
    pstr("rho offsets: "); pdec(rhook); pstr(" of 25 match\n");
    good = rcok + rhook;
    good += check_example(1, INPUT1, STEPS1, FINAL1);
    good += check_example(2, INPUT2, STEPS2, FINAL2);
    pstr("total: "); pdec(good); pstr(" of 291 match\n");
    pstr(good == 291 ? "PASS\n" : "FAIL\n");
    return good == 291 ? 0 : 1;
}
